104	void Set::setHeader(const ColumnsWithTypeAndName & header)
105	{
106	    std::lock_guard lock(rwlock);
107	
108	    if (!data.empty())
109	        return;
110	
111	    keys_size = header.size();
112	    ColumnRawPtrs key_columns;
113	    key_columns.reserve(keys_size);
114	    data_types.reserve(keys_size);
115	    set_elements_types.reserve(keys_size);
116	
117	    /// The constant columns to the right of IN are not supported directly. For this, they first materialize.
118	    Columns materialized_columns;
119	
120	    /// Remember the columns we will work with
121	    for (size_t i = 0; i < keys_size; ++i)
122	    {
123	        materialized_columns.emplace_back(header.at(i).column->convertToFullColumnIfConst());
124	        key_columns.emplace_back(materialized_columns.back().get());
125	        data_types.emplace_back(header.at(i).type);
126	        set_elements_types.emplace_back(header.at(i).type);
127	
128	        /// Convert low cardinality column to full.
129	        if (const auto * low_cardinality_type = typeid_cast<const DataTypeLowCardinality *>(data_types.back().get()))
130	        {
131	            data_types.back() = low_cardinality_type->getDictionaryType();
132	            materialized_columns.emplace_back(key_columns.back()->convertToFullColumnIfLowCardinality());
133	            key_columns.back() = materialized_columns.back().get();
134	        }
135	    }
136	
137	    /// We will insert to the Set only keys, where all components are not NULL.
138	    ConstNullMapPtr null_map{};
139	    ColumnPtr null_map_holder;
