141	    {
142	        /// We convert nullable columns to non nullable we also need to update nullable types
143	        for (size_t i = 0; i < set_elements_types.size(); ++i)
144	        {
145	            data_types[i] = removeNullable(data_types[i]);
146	            set_elements_types[i] = removeNullable(set_elements_types[i]);
147	        }
148	
149	        extractNestedColumnsAndNullMap(key_columns, null_map);
150	    }
151	
152	    if (fill_set_elements)
153	    {
154	        /// Create empty columns with set values in advance.
155	        /// It is needed because set may be empty, so method 'insertFromBlock' will be never called.
156	        set_elements.reserve(keys_size);
