82	void SetOrJoinSink::consume(Chunk chunk)
83	{
84	    /// Sort columns in the block. This is necessary, since Set and Join count on the same column order in different blocks.
85	    Block sorted_block = getHeader().cloneWithColumns(chunk.detachColumns()).sortColumns();
86	
87	    table.insertBlock(sorted_block, getContext());
88	    if (persistent)
89	        backup_stream.write(sorted_block);
90	}
91	
92	void SetOrJoinSink::onFinish()
93	{
94	    table.finishInsert();
95	    if (persistent)
96	    {
97	        backup_stream.flush();
98	        compressed_backup_buf.next();
99	        backup_buf->next();
100	        backup_buf->finalize();
101	
102	        table.disk->replaceFile(fs::path(backup_tmp_path) / backup_file_name, fs::path(backup_path) / backup_file_name);
103	    }
104	}
