77	// returns keys may be filter by condition
78	static bool traverseASTFilter(
79	    const String & primary_key, const DataTypePtr & primary_key_type, const ASTPtr & elem, const PreparedSets & sets, FieldVectorPtr & res)
80	{
81	    const auto * function = elem->as<ASTFunction>();
82	    if (!function)
83	        return false;
84	
85	    if (function->name == "and")
86	    {
87	        // one child has the key filter condition is ok
88	        for (const auto & child : function->arguments->children)
89	            if (traverseASTFilter(primary_key, primary_key_type, child, sets, res))
90	                return true;
91	        return false;
92	    }
93	    else if (function->name == "or")
94	    {
95	        // make sure every child has the key filter condition
96	        for (const auto & child : function->arguments->children)
97	            if (!traverseASTFilter(primary_key, primary_key_type, child, sets, res))
98	                return false;
99	        return true;
100	    }
101	    else if (function->name == "equals" || function->name == "in")
102	    {
103	        const auto & args = function->arguments->as<ASTExpressionList &>();
104	        const ASTIdentifier * ident;
105	        const IAST * value;
106	
107	        if (args.children.size() != 2)
108	            return false;
109	
110	        if (function->name == "in")
111	        {
112	            ident = args.children.at(0)->as<ASTIdentifier>();
113	            if (!ident)
114	                return false;
115	
116	            if (ident->name() != primary_key)
117	                return false;
118	            value = args.children.at(1).get();
119	
120	            PreparedSetKey set_key;
121	            if ((value->as<ASTSubquery>() || value->as<ASTIdentifier>()))
122	                set_key = PreparedSetKey::forSubquery(*value);
123	            else
124	                set_key = PreparedSetKey::forLiteral(*value, {primary_key_type});
125	
126	            auto set_it = sets.find(set_key);
127	            if (set_it == sets.end())
128	                return false;
129	            SetPtr prepared_set = set_it->second;
130	
131	            if (!prepared_set->hasExplicitSetElements())
132	                return false;
133	
134	            prepared_set->checkColumnsNumber(1);
135	            const auto & set_column = *prepared_set->getSetElements()[0];
136	            for (size_t row = 0; row < set_column.size(); ++row)
137	                res->push_back(set_column[row]);
138	            return true;
139	        }
140	        else
141	        {
142	            if ((ident = args.children.at(0)->as<ASTIdentifier>()))
143	                value = args.children.at(1).get();
144	            else if ((ident = args.children.at(1)->as<ASTIdentifier>()))
145	                value = args.children.at(0).get();
146	            else
147	                return false;
148	
149	            if (ident->name() != primary_key)
150	                return false;
151	
152	            /// function->name == "equals"
153	            if (const auto * literal = value->as<ASTLiteral>())
154	            {
155	                auto converted_field = convertFieldToType(literal->value, *primary_key_type);
156	                if (!converted_field.isNull())
157	                    res->push_back(converted_field);
158	                return true;
159	            }
160	        }
161	    }
162	    return false;
163	}
