165	/** Retrieve from the query a condition of the form `key = 'key'`, `key in ('xxx_'), from conjunctions in the WHERE clause.
166	  * TODO support key like search
167	  */
168	static std::pair<FieldVectorPtr, bool> getFilterKeys(
169	    const String & primary_key, const DataTypePtr & primary_key_type, const SelectQueryInfo & query_info)
170	{
171	    const auto & select = query_info.query->as<ASTSelectQuery &>();
172	    if (!select.where())
173	        return {{}, true};
174	
175	    FieldVectorPtr res = std::make_shared<FieldVector>();
176	    auto matched_keys = traverseASTFilter(primary_key, primary_key_type, select.where(), query_info.sets, res);
177	    return std::make_pair(res, !matched_keys);
178	}
