180	template <typename K, typename V>
181	static void fillColumns(const K & key, const V & value, size_t key_pos, const Block & header, MutableColumns & columns)
182	{
183	    ReadBufferFromString key_buffer(key);
184	    ReadBufferFromString value_buffer(value);
185	    for (size_t i = 0; i < header.columns(); ++i)
186	    {
187	        const auto & serialization = header.getByPosition(i).type->getDefaultSerialization();
188	        serialization->deserializeBinary(*columns[i], i == key_pos ? key_buffer : value_buffer);
189	    }
190	}
