192	static std::vector<std::string> serializeKeysToRawString(
193	    FieldVector::const_iterator & it,
194	    FieldVector::const_iterator end,
195	    DataTypePtr key_column_type,
196	    size_t max_block_size)
197	{
198	    size_t num_keys = end - it;
199	
200	    std::vector<std::string> result;
201	    result.reserve(num_keys);
202	
203	    size_t rows_processed = 0;
204	    while (it < end && (max_block_size == 0 || rows_processed < max_block_size))
205	    {
206	        std::string & serialized_key = result.emplace_back();
207	        WriteBufferFromString wb(serialized_key);
208	        key_column_type->getDefaultSerialization()->serializeBinary(*it, wb);
209	        wb.finalize();
210	
211	        ++it;
212	        ++rows_processed;
213	    }
214	    return result;
215	}
216	
217	static std::vector<std::string> serializeKeysToRawString(const ColumnWithTypeAndName & keys)
218	{
219	    if (!keys.column)
220	        return {};
221	
222	    size_t num_keys = keys.column->size();
223	    std::vector<std::string> result;
224	    result.reserve(num_keys);
225	
226	    for (size_t i = 0; i < num_keys; ++i)
227	    {
228	        std::string & serialized_key = result.emplace_back();
229	        WriteBufferFromString wb(serialized_key);
230	        Field field;
231	        keys.column->get(i, field);
232	        /// TODO(@vdimir): use serializeBinaryBulk
233	        keys.type->getDefaultSerialization()->serializeBinary(field, wb);
234	        wb.finalize();
235	    }
236	    return result;
237	}
