247	class EmbeddedRocksDBSource : public ISource
248	{
249	public:
250	    EmbeddedRocksDBSource(
251	        const StorageEmbeddedRocksDB & storage_,
252	        const Block & header,
253	        FieldVectorPtr keys_,
254	        FieldVector::const_iterator begin_,
255	        FieldVector::const_iterator end_,
256	        const size_t max_block_size_)
257	        : ISource(header)
258	        , storage(storage_)
259	        , primary_key_pos(getPrimaryKeyPos(header, storage.getPrimaryKey()))
260	        , keys(keys_)
261	        , begin(begin_)
262	        , end(end_)
263	        , it(begin)
264	        , max_block_size(max_block_size_)
265	    {
266	    }
267	
268	    EmbeddedRocksDBSource(
269	        const StorageEmbeddedRocksDB & storage_,
270	        const Block & header,
271	        std::unique_ptr<rocksdb::Iterator> iterator_,
272	        const size_t max_block_size_)
273	        : ISource(header)
274	        , storage(storage_)
275	        , primary_key_pos(getPrimaryKeyPos(header, storage.getPrimaryKey()))
276	        , iterator(std::move(iterator_))
277	        , max_block_size(max_block_size_)
278	    {
279	    }
280	
281	    String getName() const override { return storage.getName(); }
282	
283	    Chunk generate() override
284	    {
285	        if (keys)
286	            return generateWithKeys();
287	        return generateFullScan();
288	    }
289	
290	    Chunk generateWithKeys()
291	    {
292	        const auto & sample_block = getPort().getHeader();
293	        if (it >= end)
294	        {
295	            it = {};
296	            return {};
297	        }
298	
299	        const auto & key_column_type = sample_block.getByName(storage.getPrimaryKey().at(0)).type;
300	        auto raw_keys = serializeKeysToRawString(it, end, key_column_type, max_block_size);
301	        return storage.getBySerializedKeys(raw_keys, nullptr);
302	    }
303	
304	    Chunk generateFullScan()
305	    {
306	        if (!iterator->Valid())
307	            return {};
308	
309	        const auto & sample_block = getPort().getHeader();
310	        MutableColumns columns = sample_block.cloneEmptyColumns();
311	
312	        for (size_t rows = 0; iterator->Valid() && rows < max_block_size; ++rows, iterator->Next())
313	        {
314	            fillColumns(iterator->key(), iterator->value(), primary_key_pos, getPort().getHeader(), columns);
315	        }
316	
317	        if (!iterator->status().ok())
318	        {
319	            throw Exception("Engine " + getName() + " got error while seeking key value data: " + iterator->status().ToString(),
320	                ErrorCodes::ROCKSDB_ERROR);
321	        }
322	        Block block = sample_block.cloneWithColumns(std::move(columns));
323	        return Chunk(block.getColumns(), block.rows());
324	    }
