326	private:
327	    const StorageEmbeddedRocksDB & storage;
328	
329	    size_t primary_key_pos;
330	
331	    /// For key scan
332	    FieldVectorPtr keys = nullptr;
333	    FieldVector::const_iterator begin;
334	    FieldVector::const_iterator end;
335	    FieldVector::const_iterator it;
336	
337	    /// For full scan
338	    std::unique_ptr<rocksdb::Iterator> iterator = nullptr;
339	
340	    const size_t max_block_size;
341	};
