398	    }
399	    if (config.has("rocksdb.column_family_options"))
400	    {
401	        auto column_family_options = getOptionsFromConfig(config, "rocksdb.column_family_options");
402	        status = rocksdb::GetColumnFamilyOptionsFromMap(merged, column_family_options, &merged);
403	        if (!status.ok())
404	        {
405	            throw Exception(ErrorCodes::ROCKSDB_ERROR, "Fail to merge rocksdb options from 'rocksdb.options' at: {}: {}",
406	                rocksdb_dir, status.ToString());
407	        }
408	    }
409	
410	    if (config.has("rocksdb.tables"))
411	    {
412	        auto table_name = getStorageID().getTableName();
413	
414	        Poco::Util::AbstractConfiguration::Keys keys;
415	        config.keys("rocksdb.tables", keys);
416	
417	        for (const auto & key : keys)
418	        {
419	            const String key_prefix = "rocksdb.tables." + key;
420	            if (config.getString(key_prefix + ".name") != table_name)
421	                continue;
422	
423	            String config_key = key_prefix + ".options";
424	            if (config.has(config_key))
425	            {
426	                auto table_config_options = getOptionsFromConfig(config, config_key);
427	                status = rocksdb::GetDBOptionsFromMap(merged, table_config_options, &merged);
428	                if (!status.ok())
429	                {
430	                    throw Exception(ErrorCodes::ROCKSDB_ERROR, "Fail to merge rocksdb options from '{}' at: {}: {}",
431	                        config_key, rocksdb_dir, status.ToString());
432	                }
433	            }
434	
435	            config_key = key_prefix + ".column_family_options";
436	            if (config.has(config_key))
437	            {
438	                auto table_column_family_options = getOptionsFromConfig(config, config_key);
439	                status = rocksdb::GetColumnFamilyOptionsFromMap(merged, table_column_family_options, &merged);
