442	                    throw Exception(ErrorCodes::ROCKSDB_ERROR, "Fail to merge rocksdb options from '{}' at: {}: {}",
443	                        config_key, rocksdb_dir, status.ToString());
444	                }
445	            }
446	        }
447	    }
448	
449	    status = rocksdb::DB::Open(merged, rocksdb_dir, &db);
450	
451	    if (!status.ok())
452	    {
453	        throw Exception(ErrorCodes::ROCKSDB_ERROR, "Fail to open rocksdb path at: {}: {}",
