459	
460	Pipe StorageEmbeddedRocksDB::read(
461	        const Names & column_names,
462	        const StorageSnapshotPtr & storage_snapshot,
463	        SelectQueryInfo & query_info,
464	        ContextPtr /*context*/,
465	        QueryProcessingStage::Enum /*processed_stage*/,
466	        size_t max_block_size,
467	        unsigned num_streams)
468	{
469	    storage_snapshot->check(column_names);
470	
471	    FieldVectorPtr keys;
472	    bool all_scan = false;
473	
474	    Block sample_block = storage_snapshot->metadata->getSampleBlock();
475	    auto primary_key_data_type = sample_block.getByName(primary_key).type;
476	    std::tie(keys, all_scan) = getFilterKeys(primary_key, primary_key_data_type, query_info);
477	    if (all_scan)
478	    {
479	        auto iterator = std::unique_ptr<rocksdb::Iterator>(rocksdb_ptr->NewIterator(rocksdb::ReadOptions()));
480	        iterator->SeekToFirst();
481	        return Pipe(std::make_shared<EmbeddedRocksDBSource>(*this, sample_block, std::move(iterator), max_block_size));
482	    }
483	    else
484	    {
485	        if (keys->empty())
486	            return {};
487	
488	        ::sort(keys->begin(), keys->end());
489	        keys->erase(std::unique(keys->begin(), keys->end()), keys->end());
490	
491	        Pipes pipes;
492	
493	        size_t num_keys = keys->size();
494	        size_t num_threads = std::min<size_t>(num_streams, keys->size());
495	
496	        assert(num_keys <= std::numeric_limits<uint32_t>::max());
497	        assert(num_threads <= std::numeric_limits<uint32_t>::max());
498	
499	        for (size_t thread_idx = 0; thread_idx < num_threads; ++thread_idx)
500	        {
501	            size_t begin = num_keys * thread_idx / num_threads;
502	            size_t end = num_keys * (thread_idx + 1) / num_threads;
503	
504	            pipes.emplace_back(std::make_shared<EmbeddedRocksDBSource>(
505	                    *this, sample_block, keys, keys->begin() + begin, keys->begin() + end, max_block_size));
506	        }
507	        return Pipe::unitePipes(std::move(pipes));
508	    }
509	}
