557	Chunk StorageEmbeddedRocksDB::getByKeys(
558	    const ColumnsWithTypeAndName & keys,
559	    PaddedPODArray<UInt8> & null_map) const
560	{
561	    if (keys.size() != 1)
562	        throw Exception(ErrorCodes::LOGICAL_ERROR, "StorageEmbeddedRocksDB supports only one key, got: {}", keys.size());
563	
564	    auto raw_keys = serializeKeysToRawString(keys[0]);
565	
566	    if (raw_keys.size() != keys[0].column->size())
567	        throw DB::Exception(ErrorCodes::LOGICAL_ERROR, "Assertion failed: {} != {}", raw_keys.size(), keys[0].column->size());
568	
569	    return getBySerializedKeys(raw_keys, &null_map);
570	}
571	
572	Chunk StorageEmbeddedRocksDB::getBySerializedKeys(
573	    const std::vector<std::string> & keys,
574	    PaddedPODArray<UInt8> * null_map) const
575	{
576	    std::vector<String> values;
577	    Block sample_block = getInMemoryMetadataPtr()->getSampleBlock();
578	
579	    size_t primary_key_pos = getPrimaryKeyPos(sample_block, getPrimaryKey());
580	
581	    MutableColumns columns = sample_block.cloneEmptyColumns();
582	
583	    /// Convert from vector of string to vector of string refs (rocksdb::Slice), because multiGet api expects them.
584	    std::vector<rocksdb::Slice> slices_keys;
585	    slices_keys.reserve(keys.size());
586	    for (const auto & key : keys)
587	        slices_keys.emplace_back(key);
588	
589	
590	    auto statuses = multiGet(slices_keys, values);
591	    if (null_map)
592	    {
593	        null_map->clear();
594	        null_map->resize_fill(statuses.size(), 1);
595	    }
596	
597	    for (size_t i = 0; i < statuses.size(); ++i)
598	    {
599	        if (statuses[i].ok())
600	        {
601	            fillColumns(slices_keys[i], values[i], primary_key_pos, sample_block, columns);
602	        }
603	        else if (statuses[i].IsNotFound())
604	        {
605	            if (null_map)
606	            {
607	                (*null_map)[i] = 0;
608	                for (size_t col_idx = 0; col_idx < sample_block.columns(); ++col_idx)
609	                {
610	                    columns[col_idx]->insert(sample_block.getByPosition(col_idx).type->getDefault());
611	                }
612	            }
613	        }
614	        else
615	        {
616	            throw DB::Exception(ErrorCodes::ROCKSDB_ERROR, "rocksdb error {}", statuses[i].ToString());
617	        }
618	    }
619	
620	    size_t num_rows = columns.at(0)->size();
621	    return Chunk(std::move(columns), num_rows);
622	}
